; The city constants shared by every city: the base and landing pad
; position, the perimeter wall's colour family.  The cities themselves
; (maps, cell colours, palettes) are data files, ZPDATA/CITYnn.ZPC,
; loaded at the start of each level (level_load.asm).

PAD_CODE        equ 16      ; map code of the base landing pad
TERRACE_CODE    equ 17      ; the terrace round it (0.25 height units)
PAD_H           equ 64     ; its height (0.5 height units)
PAD_X           equ 32      ; base landing pad cell (gentables.py)
PAD_COL         equ $FC     ; its city_col (colour family * 4)
TERRACE_COL     equ $F8     ; the terrace's city_col
TERRACE_R       equ 2       ; terrace: cells 1..TERRACE_R from the pad
PAD_Z           equ 32
BASE_YAW        equ 0      ; start heading: north up the boulevard
WALL_FAMILY     equ 0       ; perimeter wall colour family (gentables.py)
        ASSERT GRID == 64   ; gentables.py and zpolice.asm agree
LEVEL_LAST      equ 50      ; the last level (gentables.py)
CITY_LEVELS     equ 5       ; levels played in each city (gentables.py)
